source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    row_seps = set(sep_rows)
    col_seps = set(sep_cols)
    def spans(n, cuts):
        out=[]; start=0
        for cut in cuts:
            if start < cut: out.append((start, cut))
            start=cut+1
        if start<n: out.append((start,n))
        return out
    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    active=[]
    for ri,(r0,r1) in enumerate(rs):
        for ci,(c0,c1) in enumerate(cs):
            cells=[(r-r0,c-c0,grid[r][c]) for r in range(r0,r1) for c in range(c0,c1) if grid[r][c] != bg]
            if cells: active.append((len(cells), ri, ci, cells))
    _, _, _, pattern = max(active)
    out=[row[:] for row in grid]
    for r0,r1 in rs:
        for c0,c1 in cs:
            for r in range(r0,r1):
                for c in range(c0,c1): out[r][c]=bg
    for r0,r1 in rs:
        for c0,c1 in cs:
            for dr,dc,color in pattern:
                if dr < r1-r0 and dc < c1-c0: out[r0+dr][c0+dc]=color
    return out
